// Saves frames rendered to /tmp/frame.bmp one at a time (+ per-frame copies).
const fs = require('fs');
const path = require('path');

function findFile(cands) {
  for (const c of cands) { try { if (fs.existsSync(c) && fs.statSync(c).isFile()) return c; } catch {} }
  return null;
}
const ELF_CANDS = [
  path.join(process.cwd(), 'vm.js') && path.join(process.cwd(), 'doomgeneric_mips'),
  '/app/doomgeneric_mips',
  './doomgeneric_mips',
  '/app/doomgeneric/doomgeneric/doomgeneric_mips',
  './doomgeneric/doomgeneric/doomgeneric_mips',
  path.join(__dirname, 'doomgeneric_mips'),
  path.join(__dirname, 'doomgeneric/doomgeneric/doomgeneric_mips'),
];
const elfPath = findFile(ELF_CANDS);
if (!elfPath) {
  console.error('vm.js: could not find doomgeneric_mips ELF. looked at:', ELF_CANDS);
  process.exit(1);
}
console.log(`vm.js: loading ${elfPath} (${fs.statSync(elfPath).size} bytes)`);

// ---------- ELF loading ----------
const elf = fs.readFileSync(elfPath);
function u16(o){ return elf[o] | (elf[o+1]<<8); }
function u32(o){ return (elf[o] | (elf[o+1]<<8) | (elf[o+2]<<16) | (elf[o+3]<<24))>>>0; }
if (!(elf[0]===0x7f&&elf[1]===0x45&&elf[2]===0x4c&&elf[3]===0x46)) { console.error('not ELF'); process.exit(1); }
if (elf[4]!==1||elf[5]!==1) { console.error('not 32-bit LE'); process.exit(1); }
const e_phoff=u32(0x1C), e_phentsize=u16(0x2A), e_phnum=u16(0x2C);
const entry=u32(0x18);
console.log(`vm.js: entry=0x${entry.toString(16)} phoff=${e_phoff} phnum=${e_phnum}`);

// ---------- sparse memory (4KB pages) ----------
const PAGE_BITS=12, PAGE_SIZE=1<<PAGE_BITS, PAGE_MASK=PAGE_SIZE-1;
const NUM_PAGES=1<<20; // covers 4GB with 4KB pages
const pages=new Array(NUM_PAGES).fill(null);
function getPage(idx, create){
  let p=pages[idx];
  if(!p && create){ p=new Uint8Array(PAGE_SIZE); pages[idx]=p; }
  return p;
}
function loadU8(a){
  a=a>>>0; const pg=getPage(a>>>PAGE_BITS,false);
  if(!pg) return 0;
  return pg[a&PAGE_MASK];
}
function storeU8(a,v){
  a=a>>>0; let pg=getPage(a>>>PAGE_BITS,true); pg[a&PAGE_MASK]=v&0xFF;
}
// fast aligned word fetch for code; falls back to bytes
function loadU32(a){
  a=a>>>0;
  const off=a&PAGE_MASK;
  if((a&3)===0 && off<=PAGE_SIZE-4){
    const pg=getPage(a>>>PAGE_BITS,false);
    if(!pg) return 0;
    return (pg[off]|(pg[off+1]<<8)|(pg[off+2]<<16)|(pg[off+3]<<24))>>>0;
  }
  return ((loadU8(a)| (loadU8(a+1)<<8)|(loadU8(a+2)<<16)|(loadU8(a+3)<<24))>>>0);
}
function storeU32(a,v){
  a=a>>>0; v=v>>>0;
  const off=a&PAGE_MASK;
  if((a&3)===0 && off<=PAGE_SIZE-4){
    let pg=getPage(a>>>PAGE_BITS,true);
    pg[off]=v&0xFF; pg[off+1]=(v>>>8)&0xFF; pg[off+2]=(v>>>16)&0xFF; pg[off+3]=(v>>>24)&0xFF;
    return;
  }
  storeU8(a,v&0xFF); storeU8(a+1,(v>>>8)&0xFF); storeU8(a+2,(v>>>16)&0xFF); storeU8(a+3,(v>>>24)&0xFF);
}
function loadU16(a){
  a=a>>>0; const off=a&PAGE_MASK;
  if((a&1)===0 && off<=PAGE_SIZE-2){ const pg=getPage(a>>>PAGE_BITS,false); if(!pg) return 0; return pg[off]|(pg[off+1]<<8); }
  return loadU8(a)|(loadU8(a+1)<<8);
}
